  "risk": {
    "level": "high",
    "touches": ["validation"],
    "why": "A bug in snapshot parsing, hashing, or direct LevelDB serialization could corrupt the assumeutxo UTXO set, causing nodes to run on an invalid chainstate."
  }
}
